import React, { useState, useRef, useEffect } from 'react';

function formatTime(s) {
  if (!s || isNaN(s)) return '0:00';
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return `${m}:${sec.toString().padStart(2, '0')}`;
}

export default function Player({ track }) {
  const [playing, setPlaying] = useState(false);
  const [current, setCurrent] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(0.8);
  const audioRef = useRef(new Audio());

  // When a new track comes in, load and auto-play it
  useEffect(() => {
    const audio = audioRef.current;
    if (!track?.preview) return;
    audio.src = track.preview;
    audio.volume = volume;
    audio.load();
    audio.play()
      .then(() => setPlaying(true))
      .catch(() => setPlaying(false));
    setCurrent(0);
    setDuration(0);
  }, [track?.preview]);

  useEffect(() => {
    const audio = audioRef.current;
    const onTime = () => setCurrent(audio.currentTime);
    const onMeta = () => setDuration(audio.duration);
    const onEnd  = () => { setPlaying(false); setCurrent(0); };
    audio.addEventListener('timeupdate', onTime);
    audio.addEventListener('loadedmetadata', onMeta);
    audio.addEventListener('ended', onEnd);
    return () => {
      audio.removeEventListener('timeupdate', onTime);
      audio.removeEventListener('loadedmetadata', onMeta);
      audio.removeEventListener('ended', onEnd);
    };
  }, []);

  function togglePlay() {
    const audio = audioRef.current;
    if (!track?.preview) return;
    if (playing) { audio.pause(); setPlaying(false); }
    else { audio.play().then(() => setPlaying(true)).catch(() => {}); }
  }

  function seek(e) {
    const audio = audioRef.current;
    const rect = e.currentTarget.getBoundingClientRect();
    const ratio = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    audio.currentTime = ratio * duration;
    setCurrent(ratio * duration);
  }

  function changeVolume(v) {
    setVolume(v);
    audioRef.current.volume = v;
  }

  const progress = duration ? (current / duration) * 100 : 0;
  const bars = [1, 2, 3, 4];

  return (
    <footer style={styles.player}>
      {/* Track Info */}
      <div style={styles.trackInfo}>
        <div style={styles.thumb}>
          {track?.thumb
            ? <img src={track.thumb} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: 8 }} />
            : <div style={styles.thumbPlaceholder} />
          }
          {playing && (
            <div style={styles.barsOverlay}>
              {bars.map(i => <div key={i} style={{ ...styles.bar, animationDelay: `${i * 0.15}s` }} />)}
            </div>
          )}
        </div>
        <div style={{ minWidth: 0 }}>
          <div style={styles.trackName}>{track?.name || 'No track selected'}</div>
          <div style={styles.trackArtist}>{track?.artist || 'Click a track to play'}</div>
        </div>
        <button style={styles.heartBtn}>♡</button>
      </div>

      {/* Controls */}
      <div style={styles.controls}>
        <div style={styles.controlBtns}>
          <button style={styles.ctrlBtn} title="Shuffle">⇄</button>
          <button style={styles.ctrlBtn} title="Previous">⏮</button>
          <button
            style={{ ...styles.playBtn, ...(playing ? styles.playBtnActive : {}) }}
            onClick={togglePlay}
            title={playing ? 'Pause' : 'Play'}
          >
            {playing ? '⏸' : '▶'}
          </button>
          <button style={styles.ctrlBtn} title="Next">⏭</button>
          <button style={styles.ctrlBtn} title="Repeat">↻</button>
        </div>
        <div style={styles.progressRow}>
          <span style={styles.time}>{formatTime(current)}</span>
          <div style={styles.progressBar} onClick={seek}>
            <div style={{ ...styles.progressFill, width: `${progress}%` }}>
              <div style={styles.progressDot} />
            </div>
          </div>
          <span style={styles.time}>{formatTime(duration)}</span>
        </div>
      </div>

      {/* Volume */}
      <div style={styles.volumeArea}>
        <button style={styles.ctrlBtn} onClick={() => changeVolume(volume > 0 ? 0 : 0.8)}>
          {volume === 0 ? '🔇' : volume < 0.5 ? '🔉' : '🔊'}
        </button>
        <input
          type="range" min={0} max={1} step={0.01} value={volume}
          onChange={e => changeVolume(+e.target.value)}
          style={styles.volumeSlider}
        />
      </div>
    </footer>
  );
}

const styles = {
  player: {
    height: 76, background: 'linear-gradient(90deg, #1a0a2e 0%, #0d1b4b 100%)',
    borderTop: '1px solid var(--border)', display: 'flex', alignItems: 'center',
    padding: '0 28px', gap: 24, flexShrink: 0,
  },
  trackInfo: { display: 'flex', alignItems: 'center', gap: 14, width: 280, minWidth: 200 },
  thumb: { width: 46, height: 46, borderRadius: 8, background: 'var(--surface2)', overflow: 'hidden', position: 'relative', flexShrink: 0 },
  thumbPlaceholder: { width: '100%', height: '100%', background: 'linear-gradient(135deg, var(--purple), var(--blue))' },
  barsOverlay: { position: 'absolute', inset: 0, background: 'rgba(0,0,0,0.45)', display: 'flex', alignItems: 'flex-end', justifyContent: 'center', gap: 3, paddingBottom: 6 },
  bar: { width: 3, background: 'var(--pink)', borderRadius: 2, animation: 'barAnim 0.7s ease-in-out infinite' },
  trackName: { fontFamily: 'var(--font-display)', fontWeight: 700, fontSize: 13, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: 170 },
  trackArtist: { fontSize: 11, color: 'var(--muted)', marginTop: 2, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', maxWidth: 170 },
  heartBtn: { background: 'none', border: 'none', color: 'var(--muted)', cursor: 'pointer', fontSize: 17, marginLeft: 'auto', flexShrink: 0 },
  controls: { flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 8 },
  controlBtns: { display: 'flex', alignItems: 'center', gap: 20 },
  ctrlBtn: { background: 'none', border: 'none', color: 'var(--muted)', cursor: 'pointer', fontSize: 16, padding: 4, transition: 'color .15s' },
  playBtn: {
    width: 40, height: 40, borderRadius: '50%',
    background: 'linear-gradient(135deg, var(--pink), var(--purple))',
    border: 'none', color: 'white', cursor: 'pointer', fontSize: 16,
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    boxShadow: '0 0 20px rgba(247,37,133,0.4)', transition: 'transform .1s',
  },
  playBtnActive: { transform: 'scale(0.95)' },
  progressRow: { display: 'flex', alignItems: 'center', gap: 10, width: '100%', maxWidth: 440 },
  time: { fontSize: 11, color: 'var(--muted)', width: 34, flexShrink: 0, textAlign: 'center' },
  progressBar: { flex: 1, height: 4, background: 'var(--surface2)', borderRadius: 2, cursor: 'pointer', position: 'relative' },
  progressFill: { height: '100%', background: 'linear-gradient(90deg, var(--pink), var(--blue))', borderRadius: 2, position: 'relative', transition: 'width .1s' },
  progressDot: { width: 11, height: 11, borderRadius: '50%', background: 'white', position: 'absolute', right: -5, top: -3.5, boxShadow: '0 0 4px rgba(0,0,0,0.4)' },
  volumeArea: { display: 'flex', alignItems: 'center', gap: 8, width: 140, flexShrink: 0 },
  volumeSlider: { flex: 1, accentColor: 'var(--pink)', cursor: 'pointer', height: 4 },
};
